# -*- coding: utf-8 -*-
import json, os, re
SEL = r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json'
ROOT = r'D:/repository'
d = json.load(open(SEL, encoding='utf-8'))
SKIP = {'node_modules', '.git', 'dist', 'build', '.idea', '.vscode', 'unpackage', 'coverage'}
EXT = {'.vue', '.js', '.ts', '.mjs', '.json', '.scss', '.css', '.wxml', '.jsx', '.tsx'}
# basename -> list of (fullpath, topproject)
paths = {}
for dp, dns, fns in os.walk(ROOT):
    dns[:] = [x for x in dns if x not in SKIP]
    for fn in fns:
        if os.path.splitext(fn)[1] not in EXT:
            continue
        rel = os.path.relpath(dp, ROOT)
        top = rel.split(os.sep)[0]
        paths.setdefault(fn, []).append((os.path.join(dp, fn), top))

file_re = re.compile(r'[A-Za-z0-9_\-\.]+\.(?:vue|js|ts|mjs|json|scss|css)')
tick_re = re.compile(r'`([^`]+)`')
cn = re.compile(r'[\u4e00-\u9fff]')
cache = {}
def read(p):
    if p not in cache:
        try: cache[p] = open(p, encoding='utf-8', errors='ignore').read().lower()
        except Exception: cache[p] = ''
    return cache[p]

for i, c in enumerate(d['candidates']):
    content = c['content']
    fnames = sorted(set(f.split('/')[-1].split('\\')[-1] for f in file_re.findall(content)))
    toks = []
    for m in tick_re.findall(content):
        for part in re.split(r'[^A-Za-z0-9_$]+', m):
            if len(part) >= 4 and not cn.search(part): toks.append(part)
    toks = sorted(set(toks))
    # gather all real paths for hit filenames, build local blob + project set
    local_blob_parts, projs, nfound = [], [], 0
    for f in fnames:
        ps = paths.get(f, [])
        if ps: nfound += 1
        for p, top in ps:
            projs.append(top); local_blob_parts.append(read(p))
    lblob = '\n'.join(local_blob_parts)
    lhit = [t for t in toks if t.lower() in lblob]
    projs = sorted(set(projs))
    print('===%d|%s|%s' % (i+1, c['body_sha256_16'], c['uri'].split('/')[-1]))
    print('PROJ=[%s] FILES=%d/%d TOK=%d/%d HIT=[%s] MISS=[%s]' % (
        ','.join(projs[:8]), nfound, len(fnames), len(lhit), len(toks),
        ','.join(lhit[:20]), ','.join(t for t in toks if t.lower() not in lblob)[:20]))

